type Database = {
  name: string;
  description: string | null;
  provider: string;
  host: string;
  username: string;
  password: string;
  dbName: string | null;
  port: number;
  parentId: string | null;
  organizationId: string;
  serverNodeId: string;
  id: string;
  createdAt: string;
  updatedAt: string;
};

type Organization = {
  name: string | null;
  description: string | null;
  image: string | null;
  isPersonal: boolean;
  id: string;
  createdAt: string;
  updatedAt: string;
  databases: Database[];
};

type OrgRole = {
  accessLevel: number;
  userId: string;
  organizationId: string;
  id: string;
  createdAt: string;
  updatedAt: string;
  organization: Organization;
};

export type User = {
  name: string;
  email: string;
  image: string;
  isOnline: boolean;
  emailVerified: boolean | null;
  id: string;
  createdAt: string;
  updatedAt: string;
  orgRoles: OrgRole[];
  apiToken: string;
  defaultRegion?: string;
};

export type CliConfigData = {
  user: User;
};
